local ButterflyBreeder = {}
local PRODUCTS = {
    common_painted_lady_display = { name = "Navadni pisanček", silkCost = 1, glassCost = 1, time = 3, cost = 35, beauty = 18, prestige = 1, happiness = 1, description = "Razstava navadnih metuljev v stekleni vitrini." },
    ornate_moth_collection = { name = "Izrezljanja zbirka večerov", silkCost = 2, glassCost = 2, woodCost = 1, time = 6, cost = 110, beauty = 32, prestige = 4, happiness = 2, description = "Izrezljana vitrina zbirke nočnih metuljev." },
    exotic_butterfly_case = { name = "Egzotična vitrina", silkCost = 3, glassCost = 3, brassCost = 1, woodCost = 1, time = 9, cost = 260, beauty = 46, prestige = 9, happiness = 3, description = "Vitrina z egzotičnimi metulji iz daljnih dežel." },
    silver_pinned_collection = { name = "Srebrnopripeta zbirka", silkCost = 4, glassCost = 4, silverCost = 2, woodCost = 1, time = 12, cost = 680, beauty = 60, prestige = 16, happiness = 5, description = "Vitrina s srebrno pripetimi metulji za plemiče." },
    gold_trimmed_display = { name = "Zlatookrasna vitrina", silkCost = 5, glassCost = 5, goldCost = 2, silverCost = 1, woodCost = 2, jewelCost = 1, time = 16, cost = 1500, beauty = 73, prestige = 26, happiness = 7, description = "Vitrina z zlatimi okraski za visoke plemiče." },
    royal_grand_lepidoptera = { name = "Kraljevski metulji muzej", silkCost = 8, glassCost = 10, goldCost = 3, silverCost = 2, marbleCost = 3, jewelCost = 2, pearlCost = 2, time = 23, cost = 3800, beauty = 90, prestige = 56, happiness = 12, description = "Veliki kraljevski muzej metuljev z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    butterfly_house = { name = "Metuljna hiša", cost = { gold = 280, wood = 120, stone = 180, glass = 6 }, upkeep = 6, qualityBonus = 5 },
    lepidoptera_salon = { name = "Lepidopterološka dvorana", cost = { gold = 950, wood = 270, stone = 420, glass = 14, marble = 6 }, upkeep = 24, qualityBonus = 18 },
    exotic_breeding_atelier = { name = "Egzotični atelje", cost = { gold = 2300, wood = 350, stone = 660, silver = 30, glass = 22 }, upkeep = 58, qualityBonus = 30 },
    royal_lepidoptera_palace = { name = "Kraljevska metuljna palača", cost = { gold = 10500, wood = 580, stone = 980, gold = 65, jewel = 18, glass = 40 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
ButterflyBreeder.silkStock = 16; ButterflyBreeder.glassStock = 14; ButterflyBreeder.woodStock = 12; ButterflyBreeder.brassStock = 8; ButterflyBreeder.silverStock = 8; ButterflyBreeder.goldStock = 6; ButterflyBreeder.marbleStock = 8; ButterflyBreeder.jewelStock = 6; ButterflyBreeder.pearlStock = 4
ButterflyBreeder.productStock = {}; ButterflyBreeder.buildings = {}; ButterflyBreeder.maker = nil; ButterflyBreeder.activeMaking = {}; ButterflyBreeder.totalProducts = 0; ButterflyBreeder.dayTimer = 0
function ButterflyBreeder.init() ButterflyBreeder.silkStock=16; ButterflyBreeder.glassStock=14; ButterflyBreeder.woodStock=12; ButterflyBreeder.brassStock=8; ButterflyBreeder.silverStock=8; ButterflyBreeder.goldStock=6; ButterflyBreeder.marbleStock=8; ButterflyBreeder.jewelStock=6; ButterflyBreeder.pearlStock=4; ButterflyBreeder.productStock={}; ButterflyBreeder.buildings={}; ButterflyBreeder.maker=nil; ButterflyBreeder.activeMaking={}; ButterflyBreeder.totalProducts=0; ButterflyBreeder.dayTimer=0; print("[ButterflyBreeder] Royal Butterfly Breeder System initialized (6 products, 4 buildings)") end
function ButterflyBreeder.hireMaker(n,s) s=s or math.random(55,90); local c=530+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ButterflyBreeder.maker={name=n or ("Metuljar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Metuljar najet: %s (spretnost: %d)",ButterflyBreeder.maker.name,s),"success") end; return true end
function ButterflyBreeder.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ButterflyBreeder.build(id) local ok,e=ButterflyBreeder.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ButterflyBreeder.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ButterflyBreeder.getQualityBonus() local b=0; for _,bd in ipairs(ButterflyBreeder.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ButterflyBreeder.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.silkCost and ButterflyBreeder.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.glassCost and ButterflyBreeder.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.woodCost and ButterflyBreeder.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.brassCost and ButterflyBreeder.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and ButterflyBreeder.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ButterflyBreeder.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.marbleCost and ButterflyBreeder.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.jewelCost and ButterflyBreeder.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ButterflyBreeder.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ButterflyBreeder.buildings==0 then return false,"Potrebna metuljna hiša" end; if not ButterflyBreeder.maker then return false,"Potreben metuljar" end; return true end
function ButterflyBreeder.make(pt,qty) qty=qty or 1; local ok,e=ButterflyBreeder.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.silkCost then ButterflyBreeder.silkStock=ButterflyBreeder.silkStock-d.silkCost*qty end; if d.glassCost then ButterflyBreeder.glassStock=ButterflyBreeder.glassStock-d.glassCost*qty end; if d.woodCost then ButterflyBreeder.woodStock=ButterflyBreeder.woodStock-d.woodCost*qty end; if d.brassCost then ButterflyBreeder.brassStock=ButterflyBreeder.brassStock-d.brassCost*qty end; if d.silverCost then ButterflyBreeder.silverStock=ButterflyBreeder.silverStock-d.silverCost*qty end; if d.goldCost then ButterflyBreeder.goldStock=ButterflyBreeder.goldStock-d.goldCost*qty end; if d.marbleCost then ButterflyBreeder.marbleStock=ButterflyBreeder.marbleStock-d.marbleCost*qty end; if d.jewelCost then ButterflyBreeder.jewelStock=ButterflyBreeder.jewelStock-d.jewelCost*qty end; if d.pearlCost then ButterflyBreeder.pearlStock=ButterflyBreeder.pearlStock-d.pearlCost*qty end; local t=d.time; if ButterflyBreeder.maker then t=math.max(1,t-math.floor(ButterflyBreeder.maker.skill/12)) end; table.insert(ButterflyBreeder.activeMaking,{id="butterfly_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ButterflyBreeder.completeMaking(m) local q=1.0+(ButterflyBreeder.getQualityBonus()/100); if ButterflyBreeder.maker then q=q+(ButterflyBreeder.maker.skill/150) end; q=math.min(2.5,q); ButterflyBreeder.productStock[m.productType]=(ButterflyBreeder.productStock[m.productType] or 0)+m.quantity; ButterflyBreeder.totalProducts=ButterflyBreeder.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ButterflyBreeder.maker then ButterflyBreeder.maker.itemsMade=ButterflyBreeder.maker.itemsMade+m.quantity; if math.random()<0.25 then ButterflyBreeder.maker.skill=math.min(100,ButterflyBreeder.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vitrina izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"butterfly.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function ButterflyBreeder.update(dt) if not _G.state then return end; ButterflyBreeder.dayTimer=ButterflyBreeder.dayTimer+dt; if ButterflyBreeder.dayTimer>=30 then ButterflyBreeder.dayTimer=0; for i=#ButterflyBreeder.activeMaking,1,-1 do local m=ButterflyBreeder.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ButterflyBreeder.completeMaking(m); table.remove(ButterflyBreeder.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ButterflyBreeder.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ButterflyBreeder.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ButterflyBreeder.getStats() return {silkStock=ButterflyBreeder.silkStock,glassStock=ButterflyBreeder.glassStock,woodStock=ButterflyBreeder.woodStock,brassStock=ButterflyBreeder.brassStock,silverStock=ButterflyBreeder.silverStock,goldStock=ButterflyBreeder.goldStock,marbleStock=ButterflyBreeder.marbleStock,jewelStock=ButterflyBreeder.jewelStock,pearlStock=ButterflyBreeder.pearlStock,productStock=ButterflyBreeder.productStock,numBuildings=#ButterflyBreeder.buildings,hasMaker=ButterflyBreeder.maker~=nil,makerName=ButterflyBreeder.maker and ButterflyBreeder.maker.name or "—",makerSkill=ButterflyBreeder.maker and ButterflyBreeder.maker.skill or 0,activeMaking=#ButterflyBreeder.activeMaking,totalProducts=ButterflyBreeder.totalProducts} end
return ButterflyBreeder
